/**
 * Test helper — a typed MCP request attribution taken from the Rust-generated
 * envelope fixture, so tests that build bridge events never hand-write one,
 * and the write context a test passes when it calls a document mutator
 * directly instead of through the router (and, for `runJournaledEdit`, its
 * admitted reads).
 *
 * The value goes through the production validator; if Rust and the validator
 * ever disagree, every test that imports this fails at load.
 *
 * @coordinates-with src/test/fixtures/mcpRequestEnvelope.json — generated by src-tauri/src/mcp_bridge/attribution.test.rs
 * @module test/mcpAttributionFixture
 */

import fixture from "@/test/fixtures/mcpRequestEnvelope.json";
import { parseMcpAttribution } from "@/services/mcpBridge/attribution";
import { createMcpWriteContext, type McpWriteContext } from "@/services/mcpBridge/writeContext";
import type { McpAttribution, McpRequestEvent } from "@/services/mcpBridge/types";
import type { AdmittedReads } from "@/services/mcpBridge/v2/admittedReads";

function fromFixture(raw: unknown): McpAttribution {
  const parsed = parseMcpAttribution(raw);
  if (parsed === null) throw new Error("mcpRequestEnvelope.json holds an attribution the validator refuses");
  return parsed;
}

/** A verified-provider attribution with a 128-byte CJK session label. */
export const TEST_ATTRIBUTION: McpAttribution = fromFixture(fixture.envelopes.provider.attribution);

/** Complete a test event with the attribution every real request carries. */
export function withAttribution(event: Omit<McpRequestEvent, "attribution">): McpRequestEvent {
  return { ...event, attribution: TEST_ATTRIBUTION };
}

/** The context of a direct mutator call in a test: provider principal, CJK label. */
export const TEST_WRITE_CONTEXT: McpWriteContext = createMcpWriteContext(
  withAttribution({ id: "test-request", type: "vmark.document.write", args: {} }),
);

/** One attribution per principal state, as Rust generated them. */
export const FIXTURE_ATTRIBUTIONS = {
  anonymous: fromFixture(fixture.envelopes.anonymous.attribution),
  unrecognized: fromFixture(fixture.envelopes.unrecognized.attribution),
  ambiguous: fromFixture(fixture.envelopes.ambiguous.attribution),
  provider: TEST_ATTRIBUTION,
} as const satisfies Record<McpAttribution["principal"]["kind"], McpAttribution>;

/** `attribution` on another connection — e.g. the same provider connected twice. */
export function onConnection(attribution: McpAttribution, connectionId: string): McpAttribution {
  const moved = parseMcpAttribution({ ...attribution, connectionId });
  if (moved === null) throw new Error(`onConnection: ${connectionId} is not a connection id`);
  return moved;
}

/** The write context of one request made under `attribution`. */
export function contextFor(attribution: McpAttribution, type = "vmark.document.write"): McpWriteContext {
  return createMcpWriteContext({ id: `test-${attribution.connectionId}`, type, args: {}, attribution });
}

/** The admitted reads of a request that calls `runJournaledEdit` directly: an empty batch, not yet consumed. */
export function testAdmittedReads(): AdmittedReads {
  return { batch: { connectionId: TEST_ATTRIBUTION.connectionId, lifetime: { closed: false }, reads: [] }, consumed: false };
}
